#!/usr/bin/env python3
import base64,gzip,hashlib,json,os,re,sys,types
raw=gzip.decompress(base64.b64decode(''))
if hashlib.sha256(raw).hexdigest()!='2e319aaa381ebecae73de00772397d5d4b640810728be37f78606e3a62372dbf': raise SystemExit('HOLD_EMBEDDED_SOURCE_SHA')
m=types.ModuleType('_reviewed_nox_canary_v4');m.__file__='<reviewed-canary-v4>';sys.modules[m.__name__]=m
exec(compile(raw,m.__file__,'exec'),m.__dict__)
source=os.environ.get('NOX_OWNER_SOURCE_SHA','');request=os.environ.get('NOX_OWNER_REQUEST_ID','')
try:
    if not request.isdigit() or not re.fullmatch('[0-9a-f]{40}',source):raise m.Hold('HOLD_OWNER_REQUEST_CONTEXT')
    result=m.run(True,expected_source_sha=source)
except Exception as exc:
    result={'status':str(exc) if isinstance(exc,m.Hold) else 'HOLD_BOUNDED_ACCEPTANCE_FAILURE','native_canary_pass':False,'credentials_exported':False}
    if isinstance(exc,m.Hold):
        for key in ('dependency_identifiers','common_source_pin'):
            if hasattr(exc,key):result[key]=getattr(exc,key)
print('NOX_MAINT_REPAIR='+json.dumps({'kind':'native_resonance_acceptance','data':result},ensure_ascii=False,separators=(',',':')),flush=True)
ok=result.get('native_canary_pass') is True
print('NOX_MAINT_REPAIR_COMPLETE='+str(ok).lower(),flush=True)
raise SystemExit(0 if ok else 2)
